<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { Head, Link, useForm } from '@inertiajs/vue3'; const props=defineProps<{wedding:{id:number;name:string;timezone:string}}>(); const form=useForm({name:'',type:'ceremony',event_date:'',event_time:'',venue:'',address:'',is_primary:false}); function submit(){form.post(route('weddings.events.store',props.wedding.id));}
